package main

import "context"

// Service allows encrypting and decrypting data using an external Key Management Service.
type Service interface {
	// Decrypt a given bytearray to obtain the original data as bytes.
	Decrypt(ctx context.Context, uid string, req *DecryptRequest) ([]byte, error)
	// Encrypt bytes to a ciphertext.
	Encrypt(ctx context.Context, uid string, data []byte) (*EncryptResponse, error)
	// Status returns the status of the KMS.
	Status(ctx context.Context) (*StatusResponse, error)
}

// EncryptResponse is the response from the Envelope service when encrypting data.
type EncryptResponse struct {
	Ciphertext  []byte
	KeyID       string
	Annotations map[string][]byte
}

// DecryptRequest is the request to the Envelope service when decrypting data.
type DecryptRequest struct {
	Ciphertext  []byte
	KeyID       string
	Annotations map[string][]byte
}

// StatusResponse is the response from the Envelope service when getting the status of the service.
type StatusResponse struct {
	Version string
	Healthz string
	KeyID   string
}

package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"time"

	"google.golang.org/grpc"
	"google.golang.org/grpc/credentials/insecure"
	kmsapi "k8s.io/kms/apis/v2" // The Kubernetes KMS API
)

type HealthCheckService struct {
	path           string
	port           int
	pluginUnixPath string
	timeout        time.Duration
}

func (h *HealthCheckService) Start() chan error {
	host := fmt.Sprintf("0.0.0.0:%d", *healthzPort)
	errorCh := make(chan error)
	mux := http.NewServeMux()
	mux.HandleFunc(h.path, h.HandlerFunc)
	log.Println("Starting up health check server...")
	go func() {
		defer close(errorCh)
		select {
		case errorCh <- http.ListenAndServe(host, mux):
		default:
		}
	}()

	return errorCh
}

func (h *HealthCheckService) HandlerFunc(w http.ResponseWriter, r *http.Request) {
	_, cancel := context.WithTimeout(r.Context(), h.timeout)
	defer cancel()

	conn, err := grpc.NewClient(fmt.Sprintf("unix://%s", h.pluginUnixPath), grpc.WithTransportCredentials(insecure.NewCredentials()))
	if err != nil {
		http.Error(w, err.Error(), http.StatusServiceUnavailable)
	}
	defer conn.Close()

	client := kmsapi.NewKeyManagementServiceClient(conn)
	status, err := client.Status(context.Background(), &kmsapi.StatusRequest{})
	if err != nil {
		log.Printf("Health check failed: %v", err)
		http.Error(w, err.Error(), http.StatusServiceUnavailable)
	}

	log.Printf("Health check: %+v", status)
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func NewHealthCheckService(path string, port int, timeout time.Duration, pluginUnixPath string) *HealthCheckService {
	return &HealthCheckService{
		path:           path,
		port:           port,
		timeout:        timeout,
		pluginUnixPath: pluginUnixPath,
	}
}

package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"os"
	"os/signal"
	"syscall"
	"time"

	infisical "github.com/infisical/go-sdk"
)

var (
	hostUrl                   = flag.String("host-url", "https://app.infisical.com", "infisical instance URL")
	listenAddr                = flag.String("listen-addr", "/opt/infisicalkms.socket", "gRPC listen address")
	kmsKeyId                  = flag.String("kms-key", "", "Infisical KMS key ID")
	caCertificate             = flag.String("ca-certificate", "", "instance certificate for SSL/TLS")
	identityId                = flag.String("identity-id", "", "machine identity ID")
	uaClientId                = flag.String("ua-client-id", "", "universal auth client ID")
	uaClientSecret            = [REDACTED]"ua-client-secret", "", "universal auth client secret")
	resource                  = flag.String("azure-resource", "", "azure resource")
	serviceAccountKeyfilePath = flag.String("service-account-keyfile-path", "", "path of the service account file")
	healthzPort               = flag.Int("healthz-port", 8787, "port for health check")
	healthzPath               = flag.String("healthz-path", "/healthz", "path for health check")
	healthzTimeout            = flag.Duration("healthz-timeout", 20*time.Second, "RPC timeout for health check")
)

func run(grpcService *GRPCService, healthCheckService *HealthCheckService) error {
	signalsChan := make(chan os.Signal, 1)
	signal.Notify(signalsChan, syscall.SIGINT, syscall.SIGTERM)

	healthErrorChan := healthCheckService.Start()
	pluginErrorChan := grpcService.Start()

	for {
		select {
		case sig := <-signalsChan:
			return fmt.Errorf("captured %v, shutting down plugin", sig)
		case pluginErr := <-pluginErrorChan:
			return pluginErr
		case healthErr := <-healthErrorChan:
			log.Printf("Health check error: %+v", healthErr)
			return nil
		}
	}
}

func main() {
	flag.Parse()
	if *kmsKeyId == "" {
		log.Fatalln("Error: KMS key ID is missing")
	}

	infisicalClient := infisical.NewInfisicalClient(context.Background(), infisical.Config{
		SiteUrl:       *hostUrl,
		CaCertificate: *caCertificate,
	})

	auth := AuthHandler{
		infisicalClient:           &infisicalClient,
		clientId:                  *uaClientId,
		clientSecret:              [REDACTED],
		identityId:                *identityId,
		resource:                  *resource,
		serviceAccountKeyfilePath: *serviceAccountKeyfilePath,
	}
	if err := auth.login(); err != nil {
		log.Fatalf("Error authenticating with Infisical: %+v\n", err)
	}

	healthCheckService := NewHealthCheckService(
		*healthzPath,
		*healthzPort,
		*healthzTimeout,
		*listenAddr,
	)

	grpcService := NewGRPCService(*listenAddr, 20*time.Second, NewInfisicalKmsService(&infisicalClient, *kmsKeyId))

	if err := run(grpcService, healthCheckService); err != nil {
		log.Fatalf("Error running services: %+v\n", err)
	}
}

